 "index": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n<link rel=\"stylesheet\" href=\"/css/styles.css\">\n<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 32 32%22%3E%3Crect width=%2232%22 height=%2232%22 rx=%228%22 fill=%22%23006bff%22/%3E%3Cpath d=%22M22 11.5a8 8 0 1 0 0 9%22 stroke=%22white%22 stroke-width=%223.4%22 fill=%22none%22 stroke-linecap=%22round%22/%3E%3C/svg%3E\">\n<title>Slotly — Easy scheduling ahead</title>\n<meta name=\"description\" content=\"Share your booking link, let people pick a time that works, and get it on your Google Calendar automatically.\">\n</head>\n<body style=\"background:#fff\">\n<nav class=\"landing-nav\">\n  <a class=\"brand\" href=\"/?home=1\"><span class=\"brand-mark\" id=\"logo\"></span><span id=\"brand-name\">Slotly</span></a>\n  <span class=\"spacer\"></span>\n  <a class=\"btn btn-ghost\" href=\"/auth/google\">Log In</a>\n  <a class=\"btn btn-primary\" href=\"/auth/google\" id=\"nav-cta\">Get started</a>\n</nav>\n<section class=\"hero\">\n  <div>\n    <h1>Easy scheduling <em>ahead</em></h1>\n    <p>Share your booking page, let people pick a time that works, and every meeting lands on your Google Calendar with invites sent to everyone.</p>\n    <a class=\"google-btn\" href=\"/auth/google\" id=\"hero-cta\"><span class=\"g\" id=\"g-logo\"></span><span id=\"hero-cta-text\">Sign up with Google</span></a>\n    <p class=\"demo-note\" id=\"invite-note\" hidden>Invite-only. Here to book a meeting? Just use the link you were sent, no account needed.</p>\n    <p class=\"demo-note\" id=\"demo-note\" hidden>Google sign-in isn't configured on this server yet, so this opens a demo account.</p>\n  </div>\n  <div class=\"hero-art\" aria-hidden=\"true\">\n    <div class=\"mini-card\">\n      <div class=\"row\"><span class=\"avatar\" style=\"width:36px;height:36px;font-size:13px\">JD</span><div><div class=\"faint small\" style=\"font-weight:600\">Jamie Doe</div><strong>30 Minute Meeting</strong></div></div>\n      <div class=\"mini-grid\" id=\"mini-grid\"></div>\n      <div class=\"mini-times\"><span>9:00am</span><span>10:30am</span><span>2:00pm</span></div>\n    </div>\n  </div>\n</section>\n<section class=\"features\">\n  <div class=\"feature\"><div class=\"ficon\" data-icon=\"calendar\"></div><h3>Syncs with Google Calendar</h3><p>Busy times on your calendars are hidden automatically, so you're never double-booked.</p></div>\n  <div class=\"feature\"><div class=\"ficon\" data-icon=\"mail\"></div><h3>Invites sent for you</h3><p>Every booking creates a calendar event with a Google Meet link and emails invites to all guests.</p></div>\n  <div class=\"feature\"><div class=\"ficon\" data-icon=\"share\"></div><h3>Share anywhere</h3><p>Send your link, paste available times into an email, or embed your page on your website.</p></div>\n</section>\n<section class=\"data-use\">\n  <h2>How Slotly uses your Google account</h2>\n  <p>Slotly is a scheduling tool: people pick a time on your booking page and the meeting is added to your Google Calendar. When the host signs in with Google, Slotly asks for only what it needs:</p>\n  <ul>\n    <li><strong>Calendar events</strong> to create, update and cancel the meetings people book with you, including Google Meet links.</li>\n    <li><strong>Free/busy times</strong> to hide times you're already busy. Slotly never sees the details of your other events.</li>\n    <li><strong>Your list of calendars</strong> so you can choose which ones to check for conflicts.</li>\n    <li><strong>Send email</strong> only when you click \"Send\" to email booking times to a customer. Slotly cannot read your inbox.</li>\n  </ul>\n  <p>Your data is never sold, shared or used for advertising. People booking a meeting don't need an account. Read the full <a href=\"/privacy\">Privacy Policy</a>.</p>\n</section>\n<footer style=\"text-align:center;padding:0 16px 40px;font-size:14px\"><a href=\"/privacy\">Privacy Policy</a></footer>\n<script src=\"/js/common.js\"></script>\n<script>\n  document.getElementById('logo').innerHTML = S.icons.logo;\n  document.getElementById('g-logo').innerHTML = S.icons.google;\n  document.querySelectorAll('[data-icon]').forEach((el) => { el.innerHTML = S.icons[el.dataset.icon]; });\n  const grid = document.getElementById('mini-grid');\n  grid.innerHTML = ['M','T','W','T','F','S','S'].map((d) => '<span style=\"font-weight:600;color:#1a1a1a\">' + d + '</span>').join('') +\n    Array.from({ length: 28 }, (_, i) => '<span class=\"' + (i === 9 ? 's' : [2, 3, 8, 10, 15, 16, 17, 22, 24].includes(i) ? 'a' : '') + '\">' + (i + 1) + '</span>').join('');\n  S.api('/api/config').then((cfg) => {\n    document.getElementById('brand-name').textContent = cfg.appName;\n    document.title = cfg.appName + ' — Easy scheduling ahead';\n    document.getElementById('demo-note').hidden = !cfg.demo;\n    if (cfg.inviteOnly) {\n      for (const id of ['nav-cta', 'hero-cta']) document.getElementById(id).href = '/request-access';\n      document.getElementById('nav-cta').textContent = 'Request access';\n      document.getElementById('hero-cta-text').textContent = 'Request access';\n      document.getElementById('g-logo').hidden = true;\n      document.getElementById('invite-note').hidden = false;\n    }\n  }).catch(() => {});\n  const err = new URLSearchParams(location.search).get('error');\n  if (err) S.toast(err === 'access_denied' ? 'Sign-in was canceled' : 'Sign-in failed: ' + err);\n</script>\n</body>\n</html>\n",
